arguments.new:
// 7 notch pits (hemispherical) at compartment centres
for (k = [0:6]) let (ang = (k+0.5)*360/7)
    translate([notch_r*cos(ang), notch_r*sin(ang), base_h])
        sphere(r = notch_rad, $fn = 32);

arguments.old:
// 7 notch pits (hemispherical) at compartment centres
for (k = [0:6]) {
    ang = (k+0.5)*360/7;
    translate([notch_r*cos(ang), notch_r*sin(ang), base_h])
        sphere(r = notch_rad, $fn = 32);
}
